BEGIN;
SET LOCAL lock_timeout='3s'; SET LOCAL statement_timeout='15s';
LOCK TABLE public.events IN SHARE ROW EXCLUSIVE MODE;
DO $guard$ BEGIN
 IF (SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY policyname),'[]'::jsonb) FROM pg_policies p WHERE schemaname='public' AND tablename='events') IS DISTINCT FROM $snapshot$[{"cmd":"DELETE","qual":"((event_mode = 'team'::text) AND can_manage_friendly_team_event_by_sides(id, created_by_auth_user_id))","roles":["authenticated"],"tablename":"events","permissive":"PERMISSIVE","policyname":"events_delete_friendly_team_match_managers","schemaname":"public","with_check":null},{"cmd":"INSERT","qual":null,"roles":["authenticated"],"tablename":"events","permissive":"PERMISSIVE","policyname":"events_insert","schemaname":"public","with_check":"((created_by_auth_user_id = auth.uid()) AND ((club_id IS NULL) OR (EXISTS ( SELECT 1\n   FROM app_admins\n  WHERE ((app_admins.profile_id = auth.uid()) AND (app_admins.is_active = true)))) OR (EXISTS ( SELECT 1\n   FROM (club_members cm\n     JOIN player_profiles pp ON ((pp.id = cm.player_profile_id)))\n  WHERE ((cm.club_id = events.club_id) AND (pp.linked_auth_user_id = auth.uid()) AND (cm.is_active = true)))) OR (EXISTS ( SELECT 1\n   FROM club_members cm\n  WHERE ((cm.club_id = events.club_id) AND (cm.profile_id = auth.uid()) AND (cm.is_active = true))))))"},{"cmd":"SELECT","qual":"((status = 'closed'::text) AND (share_enabled = true) AND (share_token IS NOT NULL) AND (COALESCE(is_deleted, false) = false))","roles":["anon"],"tablename":"events","permissive":"PERMISSIVE","policyname":"events_public_shared_select","schemaname":"public","with_check":null},{"cmd":"SELECT","qual":"((EXISTS ( SELECT 1\n   FROM app_admins\n  WHERE ((app_admins.profile_id = auth.uid()) AND (app_admins.is_active = true)))) OR ((club_id IS NULL) AND (created_by_auth_user_id = auth.uid())) OR (EXISTS ( SELECT 1\n   FROM (club_members cm\n     JOIN player_profiles pp ON ((pp.id = cm.player_profile_id)))\n  WHERE ((cm.club_id = events.club_id) AND (pp.linked_auth_user_id = auth.uid()) AND (cm.is_active = true)))) OR (EXISTS ( SELECT 1\n   FROM club_members cm\n  WHERE ((cm.club_id = events.club_id) AND (cm.profile_id = auth.uid()) AND (cm.is_active = true)))))","roles":["authenticated"],"tablename":"events","permissive":"PERMISSIVE","policyname":"events_select","schemaname":"public","with_check":null},{"cmd":"SELECT","qual":"((event_mode = 'team'::text) AND (COALESCE(is_deleted, false) = false) AND can_view_friendly_team_event_by_sides(id, created_by_auth_user_id))","roles":["authenticated"],"tablename":"events","permissive":"PERMISSIVE","policyname":"events_select_friendly_team_match_viewers","schemaname":"public","with_check":null},{"cmd":"SELECT","qual":"is_super_user()","roles":["authenticated"],"tablename":"events","permissive":"PERMISSIVE","policyname":"events_super_user_select","schemaname":"public","with_check":null},{"cmd":"UPDATE","qual":"is_super_user()","roles":["authenticated"],"tablename":"events","permissive":"PERMISSIVE","policyname":"events_super_user_update","schemaname":"public","with_check":"is_super_user()"},{"cmd":"UPDATE","qual":"((EXISTS ( SELECT 1\n   FROM app_admins\n  WHERE ((app_admins.profile_id = auth.uid()) AND (app_admins.is_active = true)))) OR ((club_id IS NULL) AND (created_by_auth_user_id = auth.uid())) OR (EXISTS ( SELECT 1\n   FROM (club_members cm\n     JOIN player_profiles pp ON ((pp.id = cm.player_profile_id)))\n  WHERE ((cm.club_id = events.club_id) AND (pp.linked_auth_user_id = auth.uid()) AND (cm.is_active = true) AND (cm.role = ANY (ARRAY['main_admin'::text, 'sub_admin'::text]))))) OR (EXISTS ( SELECT 1\n   FROM club_members cm\n  WHERE ((cm.club_id = events.club_id) AND (cm.profile_id = auth.uid()) AND (cm.is_active = true) AND (cm.role = ANY (ARRAY['main_admin'::text, 'sub_admin'::text]))))))","roles":["authenticated"],"tablename":"events","permissive":"PERMISSIVE","policyname":"events_update_creator_or_group_admin","schemaname":"public","with_check":"((EXISTS ( SELECT 1\n   FROM app_admins\n  WHERE ((app_admins.profile_id = auth.uid()) AND (app_admins.is_active = true)))) OR ((club_id IS NULL) AND (created_by_auth_user_id = auth.uid())) OR (EXISTS ( SELECT 1\n   FROM (club_members cm\n     JOIN player_profiles pp ON ((pp.id = cm.player_profile_id)))\n  WHERE ((cm.club_id = events.club_id) AND (pp.linked_auth_user_id = auth.uid()) AND (cm.is_active = true) AND (cm.role = ANY (ARRAY['main_admin'::text, 'sub_admin'::text]))))) OR (EXISTS ( SELECT 1\n   FROM club_members cm\n  WHERE ((cm.club_id = events.club_id) AND (cm.profile_id = auth.uid()) AND (cm.is_active = true) AND (cm.role = ANY (ARRAY['main_admin'::text, 'sub_admin'::text]))))))"},{"cmd":"UPDATE","qual":"((event_mode = 'team'::text) AND (COALESCE(is_deleted, false) = false) AND can_manage_friendly_team_event_by_sides(id, created_by_auth_user_id))","roles":["authenticated"],"tablename":"events","permissive":"PERMISSIVE","policyname":"events_update_friendly_team_match_managers","schemaname":"public","with_check":"((event_mode = 'team'::text) AND (COALESCE(is_deleted, false) = false) AND (stats_mode = ANY (ARRAY['official'::text, 'record_only'::text, 'undecided'::text])) AND (status = ANY (ARRAY['active'::text, 'closed'::text])) AND can_manage_friendly_team_event_by_sides(id, created_by_auth_user_id))"},{"cmd":"DELETE","qual":"true","roles":["anon","authenticated"],"tablename":"events","permissive":"PERMISSIVE","policyname":"rls05_events_delete_compat","schemaname":"public","with_check":null},{"cmd":"SELECT","qual":"true","roles":["anon","authenticated"],"tablename":"events","permissive":"PERMISSIVE","policyname":"rls05_events_select_compat","schemaname":"public","with_check":null},{"cmd":"UPDATE","qual":"true","roles":["anon","authenticated"],"tablename":"events","permissive":"PERMISSIVE","policyname":"rls05_events_update_compat","schemaname":"public","with_check":"true"}]$snapshot$::jsonb
 OR NOT (SELECT relrowsecurity FROM pg_class WHERE oid='public.events'::regclass)
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.events'::regclass AND tgname='guard_event_identity' AND tgenabled='O')
 THEN RAISE EXCEPTION 'Event update preconditions drifted; stop'; END IF;
END $guard$;
CREATE SCHEMA events_operation_private;
REVOKE ALL ON SCHEMA events_operation_private FROM PUBLIC,anon,authenticated;
CREATE FUNCTION events_operation_private.guard_member_fields() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=''
AS $body$
BEGIN
 IF current_user NOT IN ('anon','authenticated') THEN RETURN NEW; END IF;
 IF (to_jsonb(NEW)-ARRAY['status','closed_at','stats_mode','court_count','updated_at'])
 IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','closed_at','stats_mode','court_count','updated_at'])
 AND NOT coalesce((auth.uid() IS NOT NULL AND (public.is_super_user()
 OR (OLD.club_id IS NULL AND OLD.created_by_auth_user_id=auth.uid())
 OR EXISTS(SELECT 1 FROM public.club_members cm LEFT JOIN public.player_profiles pp ON pp.id=cm.player_profile_id
 WHERE cm.club_id=OLD.club_id AND cm.is_active AND cm.role IN ('main_admin','sub_admin')
 AND (cm.profile_id=auth.uid() OR pp.linked_auth_user_id=auth.uid()))
 OR (OLD.event_mode='team' AND public.can_manage_friendly_team_event_by_sides(OLD.id,OLD.created_by_auth_user_id)))),false)
 THEN RAISE EXCEPTION '開催の管理項目を変更する権限がありません' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $body$;
REVOKE ALL ON FUNCTION events_operation_private.guard_member_fields() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER guard_event_member_fields BEFORE UPDATE ON public.events
 FOR EACH ROW EXECUTE FUNCTION events_operation_private.guard_member_fields();
CREATE POLICY rls10_events_update_members ON public.events FOR UPDATE TO authenticated USING((auth.uid() IS NOT NULL AND event_mode IN ('auto','manual') AND NOT coalesce(is_deleted,false)
 AND EXISTS(SELECT 1 FROM public.club_members cm LEFT JOIN public.player_profiles pp ON pp.id=cm.player_profile_id
 WHERE cm.club_id=events.club_id AND cm.is_active AND (cm.profile_id=auth.uid() OR pp.linked_auth_user_id=auth.uid())))) WITH CHECK((auth.uid() IS NOT NULL AND event_mode IN ('auto','manual') AND NOT coalesce(is_deleted,false)
 AND EXISTS(SELECT 1 FROM public.club_members cm LEFT JOIN public.player_profiles pp ON pp.id=cm.player_profile_id
 WHERE cm.club_id=events.club_id AND cm.is_active AND (cm.profile_id=auth.uid() OR pp.linked_auth_user_id=auth.uid()))));
ALTER POLICY events_update_friendly_team_match_managers ON public.events WITH CHECK((event_mode='team' AND stats_mode IN ('official','record_only','undecided') AND status IN ('active','closed') AND public.can_manage_friendly_team_event_by_sides(id,created_by_auth_user_id)));
DROP POLICY rls05_events_update_compat ON public.events;
COMMIT;
